from itertools import product
imp = lambda a, b: (not a) or b
S = {'S1': lambda p, q: imp(p, q), 'S2': lambda p, q: (not p) and q,
     'S3': lambda p, q: (not p) or q, 'S4': lambda p, q: (not p) or (not q)}
rows = list(product([True, False], repeat=2))
for n, s in S.items(): print(n, [int(s(p, q)) for p, q in rows])
for opt, (a, b) in {'A': ('S1', 'S3'), 'B': ('S2', 'S3'), 'C': ('S2', 'S4'), 'D': ('S1', 'S4')}.items():
    diff = [(p, q) for p, q in rows if S[a](p, q) != S[b](p, q)]
    print(opt, a, '==', b, ':', not diff, 'differs at (p,q)=', diff)
